<?php
require_once "includes/auth.php"; require_login(); require_once "config/database.php"; $pageTitle="Reports";
$from=$_GET["from"]??date("Y-m-01");$to=$_GET["to"]??date("Y-m-d");$student=(int)($_GET["student"]??0);$subject=(int)($_GET["subject"]??0);
$sql="SELECT s.student_id,s.name,COALESCE(sub.name,'All Subjects') subject_name,COUNT(a.id) total,SUM(a.status='Present') present,SUM(a.status='Absent') absent FROM attendance a JOIN students s ON s.id=a.student_id LEFT JOIN subjects sub ON sub.id=a.subject_id WHERE a.date BETWEEN ? AND ?";
$p=[$from,$to];if($student){$sql.=" AND s.id=?";$p[]=$student;}if($subject){$sql.=" AND a.subject_id=?";$p[]=$subject;}$sql.=" GROUP BY s.id,a.subject_id ORDER BY s.name,subject_name";
$st=$pdo->prepare($sql);$st->execute($p);$rows=$st->fetchAll();$students=$pdo->query("SELECT id,student_id,name FROM students ORDER BY name")->fetchAll();$subjects=$pdo->query("SELECT id,name FROM subjects ORDER BY name")->fetchAll();
require "includes/header.php";?>
<section class="panel"><div class="panel-head"><div><h2>Attendance Reports</h2><p>Generate subject-wise attendance for any date range.</p></div></div>
<form class="filters"><div><label>From</label><input type="date" name="from" value="<?=h($from)?>"></div><div><label>To</label><input type="date" name="to" value="<?=h($to)?>"></div><div><label>Student</label><select name="student"><option value="0">All students</option><?php foreach($students as $s):?><option value="<?=$s["id"]?>" <?=$student===$s["id"]?"selected":""?>><?=h($s["name"]." (".$s["student_id"].")")?></option><?php endforeach;?></select></div><div><label>Subject</label><select name="subject"><option value="0">All subjects</option><?php foreach($subjects as $s):?><option value="<?=$s["id"]?>" <?=$subject===$s["id"]?"selected":""?>><?=h($s["name"])?></option><?php endforeach;?></select></div><button class="btn primary">Generate</button></form>
<div class="table-wrap"><table><thead><tr><th>Student</th><th>Subject</th><th>Total</th><th>Present</th><th>Absent</th><th>Percentage</th></tr></thead><tbody><?php foreach($rows as $r):$pct=$r["total"]?round($r["present"]/$r["total"]*100,1):0;?><tr><td><b><?=h($r["name"])?></b><small class="sub"><?=h($r["student_id"])?></small></td><td><?=h($r["subject_name"])?></td><td><?=$r["total"]?></td><td><?=$r["present"]?></td><td><?=$r["absent"]?></td><td><strong><?=$pct?>%</strong></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6" class="empty">No attendance data in this range.</td></tr><?php endif;?></tbody></table></div></section>
<?php require "includes/footer.php"; ?>